def read(repo,path):return canonical_source(repo,path).read_text(encoding="utf8").replace("\r\n","\n")
def inventory(repo):
 rows=[]
 for name,recipe in RECIPES.items():
  text=read(repo,recipe["path"]);assert hashlib.sha256(text.encode()).hexdigest()==recipe["sourceSha256LF"]
  rows.append(dict(path=recipe["path"],mode=recipe["mode"],features=["desktop-original-message-notification-root"],sha256=recipe["sourceSha256LF"]))
 return rows
def generate(repo,out):
 files=[];proofs=[]
 for name,recipe in RECIPES.items():
  original=read(repo,recipe["path"]);assert hashlib.sha256(original.encode()).hexdigest()==recipe["sourceSha256LF"]
  text=original;applied=[]
  for edit in recipe["edits"]:
   assert text.count(edit["before"])==edit["count"],name
   positions=[];cursor=0
   for _ in range(edit["count"]):
    offset=text.index(edit["before"],cursor);positions.append(len(text[:offset].encode()))
    text=text[:offset]+edit["after"]+text[offset+len(edit["before"]):];cursor=offset+len(edit["after"])
   assert positions==edit["afterByteOffsets"]
   applied.append((positions,edit))
  inverse=text.encode()
  for positions,edit in reversed(applied):
   for offset in reversed(positions):
    after=edit["after"].encode();assert inverse[offset:offset+len(after)]==after
    inverse=inverse[:offset]+edit["before"].encode()+inverse[offset+len(after):]
  assert inverse==original.encode()
  assert hashlib.sha256(text.encode()).hexdigest()==recipe["outputSha256LF"]
  # Whole direct Policy is copied exactly once by prepareUpstreamSources.
  if recipe["mode"] != "direct":
   dest=out/recipe["output"];dest.parent.mkdir(parents=True,exist_ok=True);dest.write_text(text,encoding="utf8",newline="\n");files.append(recipe["output"])
  proofs.append(dict(source=recipe["path"],sourceSha256LF=recipe["sourceSha256LF"],output=recipe["output"],outputSha256LF=recipe["outputSha256LF"],fullActualInverse=True))
 (out/"original-message-notification-source.json").write_text(json.dumps(proofs,indent=2)+"\n",encoding="utf8",newline="\n")
 return files
